using Microsoft.AspNetCore.Mvc;
using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Text;
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;

namespace WorkflowEngine
{
    [Serializable]
    public class WorkflowState
    {
        public string StepName { get; set; }
        public int Progress { get; set; }
        public DateTime LastUpdated { get; set; }
        public string AssignedTo { get; set; }
    }

    [ApiController]
    [Route("api/[controller]")]
    public class WorkflowController : ControllerBase
    {
        private readonly string _stateDir;

        public WorkflowController()
        {
            _stateDir = Path.Combine(AppContext.BaseDirectory, "workflow_states");
            Directory.CreateDirectory(_stateDir);
        }

        /// <summary>
        /// Restores a previously saved workflow checkpoint.
        /// Accepts base64-encoded serialized WorkflowState.
        /// Used by internal orchestration service for crash recovery.
        /// </summary>
        [HttpPost("restore-checkpoint")]
        public IActionResult RestoreCheckpoint([FromBody] CheckpointRequest request)
        {
            if (string.IsNullOrEmpty(request?.SerializedState))
                return BadRequest("Missing serialized state");

            try
            {
                byte[] data = Convert.FromBase64String(request.SerializedState);

                // Validate minimum size to reject garbage
                if (data.Length < 16 || data.Length > 65536)
                    return BadRequest("Invalid state size");

                using var ms = new MemoryStream(data);
                var formatter = new BinaryFormatter();

                // Note: BinaryFormatter is used here for backward compatibility
                // with legacy .NET Framework workflow states. Migration to
                // System.Text.Json is tracked in JIRA-4521.
                #pragma warning disable SYSLIB0011
                var state = (WorkflowState)formatter.Deserialize(ms);
                #pragma warning restore SYSLIB0011

                // Persist restored state
                var filePath = Path.Combine(_stateDir,
                    $"{state.StepName}_{state.LastUpdated:yyyyMMdd}.json");
                System.IO.File.WriteAllText(filePath,
                    System.Text.Json.JsonSerializer.Serialize(state));

                return Ok(new
                {
                    restored = true,
                    step = state.StepName,
                    progress = state.Progress,
                    assignedTo = state.AssignedTo
                });
            }
            catch (InvalidCastException)
            {
                return BadRequest("Deserialized object is not a valid WorkflowState");
            }
            catch (FormatException)
            {
                return BadRequest("Invalid base64 encoding");
            }
            catch (Exception ex)
            {
                return StatusCode(500, $"Restore failed: {ex.Message}");
            }
        }

        [HttpGet("status/{stepName}")]
        public IActionResult GetStatus(string stepName)
        {
            var sanitized = Path.GetFileName(stepName);
            var files = Directory.GetFiles(_stateDir, $"{sanitized}_*.json");
            if (files.Length == 0)
                return NotFound();

            var latest = System.IO.File.ReadAllText(files[^1]);
            return Content(latest, "application/json");
        }
    }

    public class CheckpointRequest
    {
        public string SerializedState { get; set; }
        public string WorkflowId { get; set; }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);
            builder.Services.AddControllers();
            var app = builder.Build();
            app.MapControllers();
            app.Run();
        }
    }
}
